package migrate
import("context";"fmt";"os";"path/filepath";"sort";"strings";"github.com/jackc/pgx/v5/pgxpool")
func Run(ctx context.Context,db *pgxpool.Pool,dir string)error{if _,e:=db.Exec(ctx,"CREATE TABLE IF NOT EXISTS numpo_schema_migrations(version text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now())");e!=nil{return e};entries,e:=os.ReadDir(dir);if e!=nil{return e};var files []string;for _,x:=range entries{if !x.IsDir()&&strings.HasSuffix(x.Name(),".sql"){files=append(files,x.Name())}};sort.Strings(files);for _,name:=range files{var n int;if e=db.QueryRow(ctx,"SELECT count(*) FROM numpo_schema_migrations WHERE version=$1",name).Scan(&n);e!=nil{return e};if n>0{continue};b,e:=os.ReadFile(filepath.Join(dir,name));if e!=nil{return e};tx,e:=db.Begin(ctx);if e!=nil{return e};if _,e=tx.Exec(ctx,string(b));e!=nil{_ = tx.Rollback(ctx);return fmt.Errorf("%s: %w",name,e)};if _,e=tx.Exec(ctx,"INSERT INTO numpo_schema_migrations(version) VALUES($1)",name);e!=nil{_ = tx.Rollback(ctx);return e};if e=tx.Commit(ctx);e!=nil{return e}};return nil}